'use strict';
(()=>{const L=window.AutoLab,D=window.GameData,$=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),p=new window.Spectator();let b=null,config=null,rows=[],last=0,accum=0,reported=false;
 $('scenario').innerHTML=Object.entries(L.scenarios).map(([key,s])=>`<option value="${key}">${s.name}</option>`).join('');$('build').innerHTML=Object.entries(L.names).map(([key,name])=>`<option value="${key}">${name}</option>`).join('');
 const query=new URLSearchParams(location.search);for(const [id,values]of [['scenario',Object.keys(L.scenarios)],['build',Object.keys(L.names)],['policy',['attack','protect']],['operation',['traits','previous']],['ratio',['1','0.45','0.25']]])if(values.includes(query.get(id)))$(id).value=query.get(id);if(query.has('seed')){const seed=Number(query.get('seed'));if(Number.isInteger(seed)&&seed>=0&&seed<=4294967295)$('seed').value=String(seed);}
 function preview(){const build=$('build').value;$('deck-summary').textContent=L.swaps[build].map(([old,key])=>D.cards[old].name+' → '+D.cards[key].name).join(' / ')||'기초 카드 20장 그대로';const counts={};for(const c of L.deck(build))counts[c.key]=(counts[c.key]||0)+1;$('deck-list').textContent=Object.entries(counts).map(([key,n])=>D.cards[key].name+' ['+window.CardTraits.traits[D.cards[key].traits[0]].name+'] '+n+'장').join(' · ');$('deck-summary').textContent+=' / '+window.CardTraits.summary(L.deck(build)).map(r=>r.name+' '+r.level+'단계 ('+r.count+'종)').join(' · ');}
 function update(){if(!b)return;const s=b.s;$('status').textContent=b.autoPolicyLabel()+' · '+(s.autoTraitVersion===1?'특성 활용':'이전 운영')+' · '+s.t.toFixed(1)+' / 180초 · '+(s.ended?s.winner===0?'승리':s.endReason||'패배':s.paused?'일시정지':'관전 중');$('pause').disabled=s.ended;$('pause').textContent=s.paused&&!s.ended?'관전 재개':'관전 일시정지';$('decision').textContent=s.autoHold?.phase==='holding'?s.autoHold.reason:s.autoLast?s.autoLast.at.toFixed(1)+'초 · '+s.autoLast.reason:b.autoTraitStatus();$('awareness').innerHTML=window.BattleAwareness.panel(b);p.draw($('field'),b,$('moment-banner'));if(s.ended&&!reported){reported=true;rows.unshift(L.summarize(b,config));rows=rows.slice(0,8);$('results').innerHTML=rows.map(r=>`<article class="auto-lab-result"><strong>${esc(L.scenarios[r.scenario].name)} · ${esc(L.names[r.build])} · ${r.policy==='attack'?'공격':'보호'} 중심 · ${r.operation==='previous'?'이전 운영':'특성 활용'} · ${r.win?'승리':esc(r.endReason||'패배')}</strong><p>HP ${Math.round(r.ratio*100)}% · 시드 ${r.seed} · ${r.time}초 · 남은 HP 합계 ${r.hp}</p><p>회복 ${r.healed} · 엄호 피해 ${r.covered} · 차단 ${r.blocked}회 · 추가 추격 ${r.chain}회 · 카드 이동 ${r.moves}명</p><p>특성 장면 · ${Object.entries(r.traits.stats).map(([k,n])=>esc(window.CardTraits.traits[k].name)+' '+n).join(' / ')}</p><details><summary>실제 사용 카드와 마지막 운영</summary><p>${Object.entries(r.uses).map(([k,n])=>esc(D.cards[k].name)+' '+n+'회').join(' · ')}</p>${r.decisions.slice(-6).map(d=>`<p>${d.at.toFixed(1)}초 · ${esc(d.reason)}</p>`).join('')}</details></article>`).join('');for(const id of ['scenario','build','policy','operation','ratio','seed','start'])$(id).disabled=false;}}
 function start(){try{config={scenario:$('scenario').value,build:$('build').value,policy:$('policy').value,operation:$('operation').value,ratio:Number($('ratio').value),seed:Number($('seed').value)};b=L.create(config.scenario,config.build,config.policy,config.ratio,config.seed,config.operation);reported=false;accum=0;$('error').textContent='';for(const id of ['scenario','build','policy','operation','ratio','seed','start'])$(id).disabled=true;preview();update();}catch(e){$('error').textContent=e.message;}}
 function step(dt){if(b){b.step(dt);update();}}
 $('start').onclick=start;for(const id of ['scenario','build'])$(id).onchange=preview;$('pause').onclick=()=>{if(b&&!b.s.ended){b.s.paused?b.resumeAuto():b.intervene();update();}};$('presentation').onclick=()=>{p.director.setMode(p.director.mode==='full'?'simple':'full');$('presentation').textContent=p.director.mode==='full'?'연출 전체':'연출 간소';update();};$('sound').onclick=async()=>{$('sound').textContent=await p.setSound(!p.sound)?'소리 끄기':'소리 켜기';};document.addEventListener('visibilitychange',()=>{if(document.hidden&&b&&!b.s.ended&&!b.s.paused){b.intervene();update();}});
 function frame(now){const dt=Math.min(.1,(now-last)/1000||0);last=now;let changed=false;if(b&&!b.s.ended&&!b.s.paused){accum+=dt*Number($('speed').value);let ticks=0;while(accum>=.02&&ticks++<12){b.step(.02);changed=true;accum-=.02;}}else accum=0;if(b&&changed)update();requestAnimationFrame(frame);}window.autoLab={get battle(){return b;},get results(){return rows;},start,step,update,spectator:p};preview();requestAnimationFrame(frame);
})();
